CREATE PROCEDURE p(IN n INT)
BEGIN
  DECLARE i INT DEFAULT 0;
  IF n > 1 THEN
    SELECT 'many';
  ELSEIF (n = 1) THEN
    SELECT 'one';
  ELSE
    SELECT 'none';
  END IF;
  WHILE i < n DO
    SET i = i + 1;
  END WHILE;
  BEGIN
    SELECT i;
  END;
END;
CALL p(3);

