CREATE PROCEDURE q(x INT)
BEGIN
  SELECT CASE WHEN x THEN 1 END;
  SELECT CASE WHEN x > 1 THEN 'big' ELSE CASE x WHEN 1 THEN 'one' ELSE 'small' END END AS size;
  IF CASE WHEN x THEN 1 END = 1 THEN
    SELECT 'yes';
  END IF;
  CASE x
    WHEN 1 THEN SELECT 'one';
    WHEN 2 THEN IF x > 0 THEN SELECT 'two'; END IF;
    ELSE BEGIN SELECT 'other'; END;
  END CASE;
END;
