CREATE PROCEDURE l()
BEGIN
  DECLARE i INT DEFAULT 0;
  l1: LOOP
    SET i = i + 1;
    IF i > 3 THEN LEAVE l1; END IF;
  END LOOP l1;
  r1: REPEAT
    SET i = i - 1;
  UNTIL i = 0 END REPEAT r1;
  w1 : WHILE i < 2 DO
    SET i = i + 1;
  END WHILE w1;
  REPEAT SET i = i + 1; UNTIL i > 5 END REPEAT;
  LOOP LEAVE l1; END LOOP;
END;
