CREATE PROCEDURE c()
BEGIN
  SELECT begin, end FROM t;
  SELECT t.begin, t.end FROM t ORDER BY end;
  UPDATE t SET end = 1 WHERE begin = 0;
  INSERT INTO t (begin, end) VALUES (1, 2);
  SET @end = 1, @begin = 2;
  SELECT CASE WHEN end > 1 THEN end ELSE begin END FROM t;
END;
